<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue';
import { gsap } from 'gsap';
const props = defineProps<{ paper: string; reducedMotion: boolean }>();
const paperUrl = computed(() => new URL(props.paper, document.baseURI).href);
const emit = defineEmits<{ open: [] }>();
const opening = ref(0), dragging = ref(false), committed = ref(false);
let start = 0, target = 0;
function grab(e: PointerEvent) { if (committed.value) return; start = e.clientX; if (!props.reducedMotion && opening.value === 0) { const cover = (e.currentTarget as HTMLElement).querySelector('.entry-volume__cover'); if (cover) { const matrix = new DOMMatrixReadOnly(getComputedStyle(cover).transform); opening.value = Math.max(0, -Math.atan2(matrix.m31, matrix.m11) * 180 / Math.PI / 154); } } target = opening.value; dragging.value = true; gsap.killTweensOf(opening); (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); }
function pull(e: PointerEvent) { if (dragging.value) opening.value = Math.max(0,Math.min(1,target+(start-e.clientX)/Math.min(220,innerWidth*.48))); }
function finish() { if(committed.value)return; committed.value=true;dragging.value=false;gsap.to(opening,{value:1,duration:props.reducedMotion ? 0 : Math.max(.24, .62*(1-opening.value)),ease:'power2.out',overwrite:true,onComplete:()=>emit('open')}); }
function release() { if(!dragging.value)return;dragging.value=false;if(opening.value>.42)finish();else gsap.to(opening,{value:0,duration:props.reducedMotion ? 0 : .65,ease:'power3.out'}); }
onBeforeUnmount(()=>{gsap.killTweensOf(opening)});
</script>
